type CapacityState = Record<string, unknown>

type CapacityControlProps = {
  interactionEnabled: boolean
  state: CapacityState
  setState: (
    next:
      | CapacityState
      | ((current: CapacityState) => CapacityState)
  ) => void
}

const MIN_CAPACITY = 8
const MAX_CAPACITY = 60
const CAPACITY_STEP = 2

function clampCapacity(value: number) {
  return Math.min(MAX_CAPACITY, Math.max(MIN_CAPACITY, value))
}

export default function SprintCapacityControl({
  interactionEnabled,
  state,
  setState,
}: CapacityControlProps) {
  const capacity = clampCapacity(Number(state.capacity ?? 24))

  const updateCapacity = (nextValue: number) => {
    setState((current) => ({
      ...current,
      capacity: clampCapacity(nextValue),
    }))
  }

  const updateFromRange = (event: React.ChangeEvent<HTMLInputElement>) => {
    updateCapacity(Number(event.currentTarget.value))
  }

  return (
    <main
      style={{
        boxSizing: 'border-box',
        display: 'flex',
        height: '100%',
        flexDirection: 'column',
        justifyContent: 'space-between',
        gap: 16,
        padding: 24,
        border: '1px solid rgba(129, 140, 248, 0.42)',
        borderRadius: 20,
        background: 'linear-gradient(145deg, #171a24 0%, #10121a 100%)',
        color: '#f8fafc',
        fontFamily: 'Inter, ui-sans-serif, system-ui, sans-serif',
      }}
    >
      <header style={{ display: 'flex', alignItems: 'flex-start', justifyContent: 'space-between', gap: 16 }}>
        <div>
          <div style={{ color: '#a5b4fc', fontSize: 12, fontWeight: 700, letterSpacing: '0.12em', textTransform: 'uppercase' }}>
            Sprint planning
          </div>
          <h2 style={{ margin: '6px 0 0', fontSize: 22, lineHeight: 1.15 }}>Capacity</h2>
        </div>
        <div style={{ color: '#cbd5e1', fontSize: 13 }}>Available points</div>
      </header>

      <section style={{ display: 'grid', gridTemplateColumns: '48px 1fr 48px', alignItems: 'center', gap: 12 }}>
        <button
          type="button"
          aria-label="Decrease capacity"
          disabled={!interactionEnabled || capacity <= MIN_CAPACITY}
          onClick={() => updateCapacity(capacity - CAPACITY_STEP)}
          style={{
            height: 44,
            border: '1px solid #3f465c',
            borderRadius: 12,
            background: '#232737',
            color: '#f8fafc',
            fontSize: 24,
            cursor: interactionEnabled ? 'pointer' : 'default',
          }}
        >
          −
        </button>

        <div style={{ textAlign: 'center' }}>
          <strong style={{ display: 'block', fontSize: 44, lineHeight: 1, letterSpacing: '-0.04em' }}>{capacity}</strong>
          <span style={{ color: '#94a3b8', fontSize: 13 }}>points this sprint</span>
        </div>

        <button
          type="button"
          aria-label="Increase capacity"
          disabled={!interactionEnabled || capacity >= MAX_CAPACITY}
          onClick={() => updateCapacity(capacity + CAPACITY_STEP)}
          style={{
            height: 44,
            border: '1px solid #4f46e5',
            borderRadius: 12,
            background: '#4338ca',
            color: '#ffffff',
            fontSize: 24,
            cursor: interactionEnabled ? 'pointer' : 'default',
          }}
        >
          +
        </button>
      </section>

      <div>
        <input
          aria-label="Sprint capacity"
          type="range"
          min={MIN_CAPACITY}
          max={MAX_CAPACITY}
          step={CAPACITY_STEP}
          value={capacity}
          disabled={!interactionEnabled}
          onInput={updateFromRange}
          onChange={updateFromRange}
          style={{ width: '100%', accentColor: '#6366f1' }}
        />
        <div style={{ display: 'flex', justifyContent: 'space-between', marginTop: 4, color: '#64748b', fontSize: 11 }}>
          <span>{MIN_CAPACITY}</span>
          <span>Adjust before committing tiers</span>
          <span>{MAX_CAPACITY}</span>
        </div>
      </div>
    </main>
  )
}

