{
  "component": {
    "definition_id": "sprint-planning-capacity-control-v1",
    "name": "Sprint Capacity",
    "props": {},
    "source": "type CapacityState = Record<string, unknown>

type CapacityControlProps = {
  interactionEnabled: boolean
  state: CapacityState
  setState: (
    next:
      | CapacityState
      | ((current: CapacityState) => CapacityState)
  ) => void
}

const MIN_CAPACITY = 8
const MAX_CAPACITY = 60
const CAPACITY_STEP = 2

function clampCapacity(value: number) {
  return Math.min(MAX_CAPACITY, Math.max(MIN_CAPACITY, value))
}

export default function SprintCapacityControl({
  interactionEnabled,
  state,
  setState,
}: CapacityControlProps) {
  const capacity = clampCapacity(Number(state.capacity ?? 24))

  const updateCapacity = (nextValue: number) => {
    setState((current) => ({
      ...current,
      capacity: clampCapacity(nextValue),
    }))
  }

  const updateFromRange = (event: ChangeEvent<HTMLInputElement>) => {
    updateCapacity(Number(event.currentTarget.value))
  }

  return (
    <main
      style={{
        boxSizing: 'border-box',
        display: 'flex',
        height: '100%',
        flexDirection: 'column',
        justifyContent: 'space-between',
        gap: 16,
        padding: 24,
        border: '1px solid rgba(129, 140, 248, 0.42)',
        borderRadius: 20,
        background: 'linear-gradient(145deg, #171a24 0%, #10121a 100%)',
        color: '#f8fafc',
        fontFamily: 'Inter, ui-sans-serif, system-ui, sans-serif',
      }}
    >
      <header style={{ display: 'flex', alignItems: 'flex-start', justifyContent: 'space-between', gap: 16 }}>
        <div>
          <div style={{ color: '#a5b4fc', fontSize: 12, fontWeight: 700, letterSpacing: '0.12em', textTransform: 'uppercase' }}>
            Sprint planning
          </div>
